var PHONE_RE=/1[3-9]\d{9}/g;
function extractPhones(text, opts){
  opts=opts||{}; var t=String(text||'');
  var re=new RegExp(PHONE_RE.source,'g');
  var m, out=[], seen={};
  while((m=re.exec(t))!==null){
    var p=m[0];
    if(opts.unique){ if(seen[p]) continue; seen[p]=1; }
    out.push(p);
  }
  return {ok:true, phones:out, count:out.length};
}
function validPhone(p){ return /^1[3-9]\d{9}$/.test(String(p||'').trim()); }
function maskPhone(p){ var s=String(p||'').trim(); if(s.length!==11) return s; return s.slice(0,3)+'****'+s.slice(7); }

var EXPORTS={extractPhones:extractPhones,validPhone:validPhone,maskPhone:maskPhone};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PhoneExtractForgePure = EXPORTS; }
